+package com.vaadinbench;
+
+import com.vaadin.browserless.BrowserlessTest;
+import com.vaadin.browserless.ViewPackages;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.H2;
+import com.vaadin.flow.component.html.ListItem;
+import com.vaadin.flow.component.html.Span;
+import com.vaadin.flow.component.textfield.TextField;
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+@ViewPackages(classes = {MainView.class, MainLayout.class})
+public class MakeSureItClicksTest extends BrowserlessTest {
+
+    @BeforeEach
+    void setup() {
+        navigate(MainView.class);
+    }
+
+    @Test
+    void testViewStructure() {
+        assertTrue($view(H1.class).withText("Items").exists());
+        assertTrue($view(TextField.class).withLabel("Item").exists());
+        assertTrue($view(Button.class).withText("Add").exists());
+        assertTrue($view(Button.class).withText("Clear").exists());
+        assertTrue($view(Span.class).withText("Items: 0").exists());
+    }
+
+    @Test
+    void testAddItem() {
+        TextField itemField = $view(TextField.class).first();
+        itemField.setValue("Test Item");
+        $view(Button.class).withText("Add").first().click();
+
+        assertTrue($view(ListItem.class).withText("Test Item").exists());
+        assertTrue($view(Span.class).withText("Items: 1").exists());
+        assertEquals("", itemField.getValue());
+    }
+
+    @Test
+    void testAddBlankItemMarksInvalid() {
+        TextField itemField = $view(TextField.class).first();
+        itemField.setValue("");
+        $view(Button.class).withText("Add").first().click();
+
+        assertTrue(itemField.isInvalid());
+    }
+
+    @Test
+    void testAddWhitespaceItemMarksInvalid() {
+        TextField itemField = $view(TextField.class).first();
+        itemField.setValue("   ");
+        $view(Button.class).withText("Add").first().click();
+
+        assertTrue(itemField.isInvalid());
+    }
+
+    @Test
+    void testAddMultipleItems() {
+        TextField itemField = $view(TextField.class).first();
+
+        itemField.setValue("Item 1");
+        $view(Button.class).withText("Add").first().click();
+        itemField.setValue("Item 2");
+        $view(Button.class).withText("Add").first().click();
+        itemField.setValue("Item 1");
+        $view(Button.class).withText("Add").first().click();
+
+        assertEquals(3, $view(ListItem.class).all().size());
+        assertTrue($view(Span.class).withText("Items: 3").exists());
+    }
+
+    @Test
+    void testClearItems() {
+        TextField itemField = $view(TextField.class).first();
+
+        itemField.setValue("Item 1");
+        $view(Button.class).withText("Add").first().click();
+        itemField.setValue("Item 2");
+        $view(Button.class).withText("Add").first().click();
+
+        assertEquals(2, $view(ListItem.class).all().size());
+
+        $view(Button.class).withText("Clear").first().click();
+
+        assertEquals(0, $view(ListItem.class).all().size());
+        assertTrue($view(Span.class).withText("Items: 0").exists());
+    }
+}
